// Preserve compressed template entries and recompress only the edited worksheet.
// Input archives are generated by our template build tool (no ZIP64 or descriptors).
export function replaceZipEntry(template: Uint8Array, replacement: Uint8Array, entryName: string) {
  function entries(bytes: Uint8Array) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const end = bytes.length - 22;
    if (view.getUint32(end, true) !== 0x06054b50 || view.getUint16(end + 20, true) !== 0) {
      throw new Error("Unsupported workbook ZIP end record");
    }
    const count = view.getUint16(end + 10, true);
    let offset = view.getUint32(end + 16, true);
    const result = [];
    for (let i = 0; i < count; i++) {
      if (view.getUint32(offset, true) !== 0x02014b50) throw new Error("Invalid workbook ZIP directory");
      const flags = view.getUint16(offset + 8, true);
      const compressedSize = view.getUint32(offset + 20, true);
      const nameSize = view.getUint16(offset + 28, true);
      const extraSize = view.getUint16(offset + 30, true);
      const commentSize = view.getUint16(offset + 32, true);
      const start = view.getUint32(offset + 42, true);
      if ((flags & 9) || compressedSize === 0xffffffff || start === 0xffffffff) {
        throw new Error("Unsupported workbook ZIP entry");
      }
      if (view.getUint32(start, true) !== 0x04034b50) throw new Error("Invalid workbook ZIP entry");
      const localSize = 30 + view.getUint16(start + 26, true) + view.getUint16(start + 28, true) + compressedSize;
      const directorySize = 46 + nameSize + extraSize + commentSize;
      const name = new TextDecoder().decode(bytes.subarray(offset + 46, offset + 46 + nameSize));
      result.push({name, local: bytes.subarray(start, start + localSize), directory: bytes.slice(offset, offset + directorySize)});
      offset += directorySize;
    }
    return result;
  }
  const replacementEntry = entries(replacement).find(entry => entry.name === entryName);
  if (!replacementEntry) throw new Error("Replacement worksheet is missing");
  const originalEntries = entries(template);
  if (!originalEntries.some(entry => entry.name === entryName)) throw new Error("Template worksheet is missing");
  const updatedEntries = originalEntries.map(entry => entry.name === entryName ? replacementEntry : entry);
  let localSize = 0;
  for (const entry of updatedEntries) {
    new DataView(entry.directory.buffer, entry.directory.byteOffset, entry.directory.byteLength).setUint32(42, localSize, true);
    localSize += entry.local.length;
  }
  const directorySize = updatedEntries.reduce((size, entry) => size + entry.directory.length, 0);
  const output = new Uint8Array(localSize + directorySize + 22);
  let position = 0;
  for (const entry of updatedEntries) { output.set(entry.local, position); position += entry.local.length; }
  for (const entry of updatedEntries) { output.set(entry.directory, position); position += entry.directory.length; }
  const end = new DataView(output.buffer, position, 22);
  end.setUint32(0, 0x06054b50, true);
  end.setUint16(8, updatedEntries.length, true);
  end.setUint16(10, updatedEntries.length, true);
  end.setUint32(12, directorySize, true);
  end.setUint32(16, localSize, true);
  return output;
}
